tl_7s = []
for i in range(8):
    for j in range(8):
        if TL[i][j] == 7:
            tl_7s.append((i, j))
for s in tl_7s:
    print(s)

print("\nBL 3s:")
bl_3s = []
for i in range(8):
    for j in range(8):
        if BL[i][j] == 3:
            bl_3s.append((i, j))
for s in bl_3s:
    print(s)

# Check if there's a rotation mapping
def rotate_coords(r, c, cols):
    return (c, (cols-1)-r)

print("\nTL 7s rotated:")
for r, c in tl_7s:
    print(f"({r},{c}) -> {rotate_coords(r,c,8)}")

